            area(MusicArea.Castle, Music.castleZadraz)
            area(MusicArea.Battle, Music.battle)
            dungeon(Dungeons.randomCave, Music.cave)
            dungeon(Dungeons.fireShieldCave, Music.cave)
            dungeon(Dungeons.ogreCave, Music.cave)
            dungeon(Dungeons.thunTemple, Music.temple)
            castle(Castles.ydarg, Music.castleZadraz)

            // Town services and other scenes play their own ambience.
            scene(Scenes.Towne.church, Music.churchChant)
            scene(Scenes.Towne.tavern, Music.tavernCrowd)
            scene(Scenes.Towne.inn, Music.innFireside)
            scene(Scenes.Towne.smith, Music.smithForge)
            scene(Scenes.Towne.merchant, Music.merchantShop)
            scene(Scenes.Towne.hut, Music.hutFireside)
            scene(sceneId("castle.ydarg.completed"), Music.ending)
        }
    }
